'use strict';

// ============================================================================
// Lab model - data-access layer for lab orders + results (Phase 10).
// ----------------------------------------------------------------------------
// A lab order is a panel a provider/admin orders for a patient. Each order
// owns N lab_results rows (one per analyte). Patient projection excludes
// provider_notes (the PHI clinical note added after results return).
// ============================================================================

const { query, queryOne } = require('../db/query');

const ORDER_COLUMNS =
  'id, user_id, subscription_id, provider_id, status, protocol_category, ' +
  'panel_name, panel_reason, vendor, vendor_order_id, vendor_requisition_url, ' +
  'requested_at, collected_at, resulted_at, provider_notes, ' +
  'created_at, updated_at';

// Patient-facing column list: drops provider_notes so a patient endpoint
// can never accidentally return the provider's clinical note.
const PATIENT_ORDER_COLUMNS =
  'id, user_id, subscription_id, provider_id, status, protocol_category, ' +
  'panel_name, panel_reason, vendor, vendor_order_id, vendor_requisition_url, ' +
  'requested_at, collected_at, resulted_at, created_at, updated_at';

const RESULT_COLUMNS =
  'id, lab_order_id, analyte_name, value_text, unit, reference_range, ' +
  'is_abnormal, observed_at, created_at';

// Create a new lab order. status defaults to 'requested'. The vendor
// columns are populated separately by labService.createOrderWithVendor
// after the row exists. Optional `client` runs inside an existing
// transaction.
async function createOrder(data, client) {
  return queryOne(
    'INSERT INTO lab_orders ' +
      '(user_id, subscription_id, provider_id, panel_name, panel_reason, ' +
      ' protocol_category) ' +
      'VALUES ($1, $2, $3, $4, $5, $6) ' +
      'RETURNING ' + ORDER_COLUMNS,
    [
      data.userId,
      data.subscriptionId || null,
      data.providerId || null,
      data.panelName,
      data.panelReason || null,
      data.protocolCategory || null,
    ],
    client
  );
}

// Single order lookup by primary key (admin projection - includes PHI).
async function findOrderById(id) {
  return queryOne(
    'SELECT ' + ORDER_COLUMNS + ' FROM lab_orders WHERE id = $1',
    [id]
  );
}

// Patient-side single order lookup. provider_notes excluded.
async function findOrderByIdForPatient(id) {
  return queryOne(
    'SELECT ' + PATIENT_ORDER_COLUMNS + ' FROM lab_orders WHERE id = $1',
    [id]
  );
}

// Every order a patient has on file, newest-requested first. Hard-capped
// at 200 rows - the patient surface does not paginate, the cap is a
// safety net for growing histories.
async function findOrdersByUser(userId) {
  const result = await query(
    'SELECT ' + PATIENT_ORDER_COLUMNS + ' FROM lab_orders ' +
      'WHERE user_id = $1 ORDER BY requested_at DESC LIMIT 200',
    [userId]
  );
  return result.rows;
}

// Admin work queue. Lists every lab order on the platform with the full
// column set (includes provider_notes - admin scope only). Optional
// filters narrow by status; the 200-row hard cap prevents accidental
// large scans.
async function findAllOrders(filters) {
  filters = filters || {};
  if (filters.status) {
    const result = await query(
      'SELECT ' + ORDER_COLUMNS + ' FROM lab_orders ' +
        'WHERE status = $1 ORDER BY requested_at DESC LIMIT 200',
      [filters.status]
    );
    return result.rows;
  }
  const result = await query(
    'SELECT ' + ORDER_COLUMNS + ' FROM lab_orders ' +
      'ORDER BY requested_at DESC LIMIT 200'
  );
  return result.rows;
}

// Update only the columns an admin can change. The SET list is built
// dynamically so the model can distinguish "skip this column" (key
// absent on data) from "set this column" (key present, value either
// a real value or null to clear). Mirrors the visit.model B1/B2 design.
async function updateOrder(id, data) {
  const sets = [];
  const params = [];
  function bind(column, jsKey) {
    if (Object.prototype.hasOwnProperty.call(data, jsKey)) {
      params.push(data[jsKey]);
      sets.push(column + ' = $' + params.length);
    }
  }
  bind('status', 'status');
  bind('provider_id', 'providerId');
  bind('collected_at', 'collectedAt');
  bind('resulted_at', 'resultedAt');
  bind('provider_notes', 'providerNotes');
  bind('vendor', 'vendor');
  bind('vendor_order_id', 'vendorOrderId');
  bind('vendor_requisition_url', 'vendorRequisitionUrl');
  // Nothing to update means the caller passed an empty data object;
  // return the current row unchanged.
  if (sets.length === 0) {
    return findOrderById(id);
  }
  sets.push('updated_at = now()');
  params.push(id);
  const sql =
    'UPDATE lab_orders SET ' + sets.join(', ') +
    ' WHERE id = $' + params.length +
    ' RETURNING ' + ORDER_COLUMNS;
  return queryOne(sql, params);
}

// Insert a result row (one analyte) on an existing order. Optional
// `client` runs inside an existing transaction.
async function addResult(data, client) {
  return queryOne(
    'INSERT INTO lab_results ' +
      '(lab_order_id, analyte_name, value_text, unit, reference_range, ' +
      ' is_abnormal, observed_at) ' +
      'VALUES ($1, $2, $3, $4, $5, $6, $7) ' +
      'RETURNING ' + RESULT_COLUMNS,
    [
      data.labOrderId,
      data.analyteName,
      data.valueText,
      data.unit || null,
      data.referenceRange || null,
      data.isAbnormal === true,
      data.observedAt || null,
    ],
    client
  );
}

// Every result for an order, oldest-observed first so the patient sees
// the panel rendered in stable order on every load.
async function findResultsByOrder(labOrderId) {
  const result = await query(
    'SELECT ' + RESULT_COLUMNS + ' FROM lab_results ' +
      'WHERE lab_order_id = $1 ORDER BY created_at ASC',
    [labOrderId]
  );
  return result.rows;
}

module.exports = {
  createOrder: createOrder,
  findOrderById: findOrderById,
  findOrderByIdForPatient: findOrderByIdForPatient,
  findOrdersByUser: findOrdersByUser,
  findAllOrders: findAllOrders,
  updateOrder: updateOrder,
  addResult: addResult,
  findResultsByOrder: findResultsByOrder,
};

'use strict';

// ============================================================================
// Lab service - vendor wiring for lab panel ordering (Phase 10).
// ----------------------------------------------------------------------------
// Wraps the lab SaaS vendor (Labcorp / Quest in the first iteration) behind
// a single createOrderWithVendor(labOrderId) call. Until the BAA is signed
// this returns a deterministic stub URL keyed off the lab order id; the
// URL has no real ACL and is for lower-environment integration only.
// Mirrors the Phase 9 visit.service shape.
// ============================================================================

const config = require('../../config/env');
const logger = require('../../utils/logger');

const STUB_VENDOR = 'stub';
const REAL_VENDOR = 'labcorp';

// Create (or return the stub for) a lab vendor order.
//
// Returns { vendor, vendorOrderId, vendorRequisitionUrl }. The caller
// persists these on the lab_orders row. Throws on a vendor failure so
// the caller can roll back the lab order; stub mode never throws.
async function createOrderWithVendor(labOrderId) {
  const apiKey = (config.labcorp && config.labcorp.apiKey) || null;
  if (!apiKey) {
    return {
      vendor: STUB_VENDOR,
      vendorOrderId: 'stub-' + String(labOrderId),
      vendorRequisitionUrl:
        'https://stub.pepnationrx.com/lab/' +
        encodeURIComponent(String(labOrderId)),
    };
  }
  try {
    // Placeholder for the real Labcorp / Quest order-create call. Shape:
    //   POST https://api.labcorp.com/v1/orders
    //     headers: Authorization: Bearer <apiKey>
    //     body:    { patient: {...}, panel: '...' }
    //   response: { orderId, requisitionUrl }
    // The real call is gated behind a BAA-eligible plan; until that
    // lands the function never reaches this branch in production.
    throw new Error('Real lab vendor integration not yet wired.');
  } catch (err) {
    logger.error('lab.createOrderWithVendor failed', {
      labOrderId: labOrderId,
      message: err && err.message,
    });
    throw err;
  }
}

module.exports = {
  createOrderWithVendor: createOrderWithVendor,
  STUB_VENDOR: STUB_VENDOR,
  REAL_VENDOR: REAL_VENDOR,
};

'use strict';

// ============================================================================
// Lab controller - lab orders + results endpoints (Phase 10).
// ----------------------------------------------------------------------------
//   GET   /api/patient/labs                    - patient lists their orders
//   GET   /api/patient/labs/:orderId           - patient reads one order
//   GET   /api/admin/labs                      - admin work queue
//   POST  /api/admin/labs                      - admin creates an order
//   PATCH /api/admin/labs/:orderId             - admin updates an order
//   POST  /api/admin/labs/:orderId/results     - admin adds a result row
//
// PHI separation: patient-facing handlers project via presentOrderForPatient
// which strips provider_notes. The admin handler returns the full row.
// ============================================================================

const labModel = require('../models/lab.model');
const labService = require('../services/lab');
const notificationService = require('../services/notification');
const audit = require('../services/audit.service');
const errors = require('../utils/errors');
const logger = require('../utils/logger');

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const LAB_STATUSES = [
  'requested', 'collected', 'processing', 'resulted',
  'cancelled', 'abnormal_flagged',
];

function requestMeta(req) {
  return { ipAddress: req.ip, userAgent: req.get('user-agent') || null };
}

// Patient projection - excludes provider_notes regardless of source.
function presentOrderForPatient(row) {
  if (!row) return null;
  return {
    id: row.id,
    subscriptionId: row.subscription_id,
    providerId: row.provider_id,
    status: row.status,
    protocolCategory: row.protocol_category,
    panelName: row.panel_name,
    panelReason: row.panel_reason,
    vendor: row.vendor,
    vendorOrderId: row.vendor_order_id,
    vendorRequisitionUrl: row.vendor_requisition_url,
    requestedAt: row.requested_at,
    collectedAt: row.collected_at,
    resultedAt: row.resulted_at,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

// Admin projection - includes provider_notes.
function presentOrderForAdmin(row) {
  if (!row) return null;
  return Object.assign(presentOrderForPatient(row), {
    providerNotes: row.provider_notes,
  });
}

function presentResult(row) {
  if (!row) return null;
  return {
    id: row.id,
    labOrderId: row.lab_order_id,
    analyteName: row.analyte_name,
    valueText: row.value_text,
    unit: row.unit,
    referenceRange: row.reference_range,
    isAbnormal: row.is_abnormal,
    observedAt: row.observed_at,
    createdAt: row.created_at,
  };
}

// GET /api/patient/labs
async function listMyOrders(req, res, next) {
  try {
    const rows = await labModel.findOrdersByUser(req.user.id);
    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'lab.list.viewed',
      entityType: 'user',
      entityId: req.user.id,
      phiAccessed: true,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      metadata: { count: rows.length },
    });
    res.status(200).json({ orders: rows.map(presentOrderForPatient) });
  } catch (err) {
    next(err);
  }
}

// GET /api/patient/labs/:orderId
async function getMyOrder(req, res, next) {
  try {
    const orderId =
      typeof req.params.orderId === 'string'
        ? req.params.orderId.trim()
        : '';
    if (!UUID_RE.test(orderId)) {
      return next(errors.badRequest('That Lab Order Reference Is Not Valid.'));
    }
    const row = await labModel.findOrderByIdForPatient(orderId);
    if (!row) {
      return next(errors.notFound('Lab Order Not Found.'));
    }
    if (row.user_id !== req.user.id) {
      return next(errors.forbidden('You May Only View Your Own Lab Orders.'));
    }
    const results = await labModel.findResultsByOrder(orderId);
    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'lab.viewed',
      entityType: 'lab_order',
      entityId: row.id,
      phiAccessed: true,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
    });
    res.status(200).json({
      order: presentOrderForPatient(row),
      results: results.map(presentResult),
    });
  } catch (err) {
    next(err);
  }
}

// GET /api/admin/labs
async function listAllOrders(req, res, next) {
  try {
    const status =
      typeof req.query.status === 'string' ? req.query.status.trim() : '';
    if (status && LAB_STATUSES.indexOf(status) === -1) {
      return next(errors.badRequest('That Status Filter Is Not Valid.'));
    }
    const rows = await labModel.findAllOrders(status ? { status: status } : {});
    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'lab.admin.list.viewed',
      entityType: 'lab_order',
      entityId: null,
      phiAccessed: true,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      metadata: { status: status || 'all', count: rows.length },
    });
    res.status(200).json({ orders: rows.map(presentOrderForAdmin) });
  } catch (err) {
    next(err);
  }
}

// POST /api/admin/labs
async function adminCreateOrder(req, res, next) {
  try {
    const body = req.body || {};
    const userId =
      typeof body.userId === 'string' ? body.userId.trim() : '';
    if (!UUID_RE.test(userId)) {
      return next(errors.badRequest('A Valid Patient Reference Is Required.'));
    }
    const panelName =
      typeof body.panelName === 'string' ? body.panelName.trim() : '';
    if (panelName.length === 0) {
      return next(errors.badRequest('A Panel Name Is Required.'));
    }
    if (panelName.length > 200) {
      return next(errors.badRequest('Panel Name Is Too Long.'));
    }
    const panelReason =
      typeof body.panelReason === 'string' && body.panelReason.trim()
        ? body.panelReason.trim()
        : null;
    let providerId = null;
    if (typeof body.providerId === 'string' && body.providerId.trim()) {
      const trimmedProvider = body.providerId.trim();
      if (!UUID_RE.test(trimmedProvider)) {
        return next(errors.badRequest('That Provider Reference Is Not Valid.'));
      }
      providerId = trimmedProvider;
    }
    let subscriptionId = null;
    if (typeof body.subscriptionId === 'string' && body.subscriptionId.trim()) {
      const trimmedSub = body.subscriptionId.trim();
      if (!UUID_RE.test(trimmedSub)) {
        return next(errors.badRequest('That Subscription Reference Is Not Valid.'));
      }
      subscriptionId = trimmedSub;
    }
    const protocolCategory =
      typeof body.protocolCategory === 'string' && body.protocolCategory.trim()
        ? body.protocolCategory.trim()
        : null;

    const created = await labModel.createOrder({
      userId: userId,
      subscriptionId: subscriptionId,
      providerId: providerId,
      panelName: panelName,
      panelReason: panelReason,
      protocolCategory: protocolCategory,
    });

    // Wire the vendor requisition. The stub adapter is deterministic so
    // a re-call would produce the same row; failures throw and the row
    // remains intact (vendor columns null) so an admin can retry.
    try {
      const vendor = await labService.createOrderWithVendor(created.id);
      const updated = await labModel.updateOrder(created.id, {
        vendor: vendor.vendor,
        vendorOrderId: vendor.vendorOrderId,
        vendorRequisitionUrl: vendor.vendorRequisitionUrl,
      });
      if (updated) {
        Object.assign(created, updated);
      }
    } catch (err) {
      logger.warn('lab.adminCreateOrder: vendor wiring failed', {
        labOrderId: created.id,
        message: err && err.message,
      });
    }

    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'lab.admin.created',
      entityType: 'lab_order',
      entityId: created.id,
      phiAccessed: true,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      metadata: { panel: panelName, userId: userId },
    });
    res.status(201).json({ order: presentOrderForAdmin(created) });
  } catch (err) {
    next(err);
  }
}

// PATCH /api/admin/labs/:orderId
async function adminUpdateOrder(req, res, next) {
  try {
    const orderId =
      typeof req.params.orderId === 'string'
        ? req.params.orderId.trim()
        : '';
    if (!UUID_RE.test(orderId)) {
      return next(errors.badRequest('That Lab Order Reference Is Not Valid.'));
    }
    const body = req.body || {};
    const data = {};
    if (typeof body.status === 'string') {
      if (LAB_STATUSES.indexOf(body.status) === -1) {
        return next(errors.badRequest('That Status Is Not Valid.'));
      }
      data.status = body.status;
    }
    if (typeof body.providerId === 'string') {
      const trimmedProvider = body.providerId.trim();
      if (trimmedProvider === '') {
        data.providerId = null;
      } else if (!UUID_RE.test(trimmedProvider)) {
        return next(errors.badRequest('That Provider Reference Is Not Valid.'));
      } else {
        data.providerId = trimmedProvider;
      }
    }
    if (typeof body.collectedAt === 'string') {
      const trimmed = body.collectedAt.trim();
      if (trimmed === '') {
        data.collectedAt = null;
      } else {
        const parsed = new Date(trimmed);
        if (Number.isNaN(parsed.getTime())) {
          return next(errors.badRequest('That Collection Time Is Not Valid.'));
        }
        data.collectedAt = parsed.toISOString();
      }
    }
    if (typeof body.resultedAt === 'string') {
      const trimmed = body.resultedAt.trim();
      if (trimmed === '') {
        data.resultedAt = null;
      } else {
        const parsed = new Date(trimmed);
        if (Number.isNaN(parsed.getTime())) {
          return next(errors.badRequest('That Result Time Is Not Valid.'));
        }
        data.resultedAt = parsed.toISOString();
      }
    }
    if (typeof body.providerNotes === 'string') {
      const trimmed = body.providerNotes.trim();
      data.providerNotes = trimmed === '' ? null : trimmed;
    }

    const current = await labModel.findOrderById(orderId);
    if (!current) {
      return next(errors.notFound('Lab Order Not Found.'));
    }

    // Auto-stamp resulted_at when status flips to 'resulted' and it
    // was not set by the caller. Mirrors how visit.adminUpdate
    // auto-provisions the video room on a status flip.
    if (
      data.status === 'resulted' &&
      !Object.prototype.hasOwnProperty.call(data, 'resultedAt') &&
      !current.resulted_at
    ) {
      data.resultedAt = new Date().toISOString();
    }

    const updated = await labModel.updateOrder(orderId, data);
    if (!updated) {
      return next(errors.notFound('Lab Order Not Found.'));
    }

    // Notify the patient when the order lands at status='resulted' AND
    // at least one result row exists. Dedupe key includes resulted_at
    // so a re-result fires a fresh email.
    if (updated.status === 'resulted' && updated.resulted_at) {
      const results = await labModel.findResultsByOrder(orderId);
      if (results.length > 0) {
        const resultedIso = new Date(updated.resulted_at).toISOString();
        await notificationService.send({
          userId: updated.user_id,
          template: 'lab_result_ready',
          payload: { panelName: updated.panel_name },
          dedupeKey:
            'lab_result_ready:' + updated.id + ':' + resultedIso,
        });
      }
    }

    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'lab.admin.updated',
      entityType: 'lab_order',
      entityId: updated.id,
      // PHI true: handler may have written/read provider_notes.
      phiAccessed: true,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      metadata: { status: updated.status },
    });
    res.status(200).json({ order: presentOrderForAdmin(updated) });
  } catch (err) {
    next(err);
  }
}

// POST /api/admin/labs/:orderId/results
async function adminAddResult(req, res, next) {
  try {
    const orderId =
      typeof req.params.orderId === 'string'
        ? req.params.orderId.trim()
        : '';
    if (!UUID_RE.test(orderId)) {
      return next(errors.badRequest('That Lab Order Reference Is Not Valid.'));
    }
    const body = req.body || {};
    const analyteName =
      typeof body.analyteName === 'string' ? body.analyteName.trim() : '';
    if (analyteName.length === 0) {
      return next(errors.badRequest('An Analyte Name Is Required.'));
    }
    const valueText =
      typeof body.valueText === 'string' ? body.valueText.trim() : '';
    if (valueText.length === 0) {
      return next(errors.badRequest('A Result Value Is Required.'));
    }
    const unit =
      typeof body.unit === 'string' && body.unit.trim()
        ? body.unit.trim()
        : null;
    const referenceRange =
      typeof body.referenceRange === 'string' && body.referenceRange.trim()
        ? body.referenceRange.trim()
        : null;
    const isAbnormal = body.isAbnormal === true || body.isAbnormal === 'true';
    let observedAt = null;
    if (typeof body.observedAt === 'string' && body.observedAt.trim()) {
      const parsed = new Date(body.observedAt.trim());
      if (Number.isNaN(parsed.getTime())) {
        return next(errors.badRequest('That Observation Time Is Not Valid.'));
      }
      observedAt = parsed.toISOString();
    }

    const order = await labModel.findOrderById(orderId);
    if (!order) {
      return next(errors.notFound('Lab Order Not Found.'));
    }

    const created = await labModel.addResult({
      labOrderId: orderId,
      analyteName: analyteName,
      valueText: valueText,
      unit: unit,
      referenceRange: referenceRange,
      isAbnormal: isAbnormal,
      observedAt: observedAt,
    });

    const meta = requestMeta(req);
    await audit.record({
      actorUserId: req.user.id,
      actorRole: req.user.role,
      action: 'lab.admin.result.added',
      entityType: 'lab_order',
      entityId: orderId,
      phiAccessed: true,
      ipAddress: meta.ipAddress,
      userAgent: meta.userAgent,
      metadata: { analyte: analyteName, isAbnormal: isAbnormal },
    });
    res.status(201).json({ result: presentResult(created) });
  } catch (err) {
    next(err);
  }
}

module.exports = {
  listMyOrders: listMyOrders,
  getMyOrder: getMyOrder,
  listAllOrders: listAllOrders,
  adminCreateOrder: adminCreateOrder,
  adminUpdateOrder: adminUpdateOrder,
  adminAddResult: adminAddResult,
  LAB_STATUSES: LAB_STATUSES,
};

'use strict';

// ============================================================================
// Patient routes: the patient dashboard. Requires a valid access token; the
// dashboard always reflects the authenticated user.
// ============================================================================

const express = require('express');

const patientController = require('../controllers/patient.controller');
const messageController = require('../controllers/message.controller');
const insuranceController = require('../controllers/insurance.controller');
const membershipController = require('../controllers/membership.controller');
const superbillController = require('../controllers/superbill.controller');
const providerProfileController = require('../controllers/provider-profile.controller');
const visitController = require('../controllers/visit.controller');
const labController = require('../controllers/lab.controller');
const authenticate = require('../middleware/authenticate');

const router = express.Router();

// The authenticated patient's dashboard: profile, subscriptions,
// prescriptions, orders, and billing.
router.get('/dashboard', authenticate, patientController.dashboard);

// G-01: cancel a subscription the patient owns.
router.delete(
  '/subscriptions/:subscriptionId',
  authenticate,
  patientController.cancelSubscription
);

// Self-service subscription management: pause, resume, or cancel via an
// `action` field in the request body.
router.patch(
  '/subscriptions/:subscriptionId',
  authenticate,
  patientController.patchSubscription
);

// G-02: address management.
router.patch('/addresses/:addressId', authenticate, patientController.updateAddress);
router.post(
  '/addresses/:addressId/set-default',
  authenticate,
  patientController.setDefaultAddress
);
router.delete('/addresses/:addressId', authenticate, patientController.deleteAddress);

// Secure care-team messaging: list threads, read a thread, post a message.
router.get('/messages', authenticate, messageController.listPatientThreads);
router.get(
  '/messages/:threadId',
  authenticate,
  messageController.getPatientThread
);
router.post('/messages', authenticate, messageController.postPatientMessage);

// Insurance eligibility and concierge: submit a policy, run a self-service
// eligibility check, and request an assisted concierge review.
router.post(
  '/insurance/policies',
  authenticate,
  insuranceController.createPolicy
);
