// ============================================================================
// Notification templates.
// ----------------------------------------------------------------------------
// One entry per template key. Each renders a Title Case subject line and a
// plain-text body from a non-PHI payload. Payloads carry only template
// variables (names, dates, amounts, treatment names) - never clinical detail.
// A template gracefully tolerates missing payload fields so a notification is
// never blocked by an absent optional value.
// ============================================================================

// Read a payload value with a fallback, trimming surrounding whitespace.
function v(payload, key, fallback) {
  const raw = payload && payload[key];
  if (raw === undefined || raw === null || raw === '') return fallback;
  return String(raw).trim();
}

const TEMPLATES = {
  // Sent to a patient whose intake was reviewed and a prescription was signed.
  prescription_signed: {
    subject: function () {
      return 'Your Prescription Has Been Reviewed';
    },
    text: function (p) {
      return (
        'Hello ' + v(p, 'firstName', 'there') + ',\n\n' +
        'A licensed provider has reviewed your intake for ' +
        v(p, 'treatmentName', 'your treatment') + '. Sign in to your ' +
        'PepNationRX dashboard to see the decision and next steps.\n\n' +
        'PepNationRX'
      );
    },
  },

  // Sent to a patient whose intake was reviewed but NOT approved (denied or
  // needs_more_info). Using prescription_signed for these outcomes was wrong:
  // the subject "Your Prescription Has Been Reviewed" implies a script was
  // written, which is factually incorrect for a denial. This template is
  // factually neutral and directs the patient to the dashboard for details.
  intake_reviewed: {
    subject: function () {
      return 'An Update On Your PepNationRX Intake';
    },
    text: function (p) {
      return (
        'Hello ' + v(p, 'firstName', 'there') + ',\n\n' +
        'A licensed provider has completed their review of your clinical intake. ' +
        'Sign in to your PepNationRX dashboard to see the outcome and any next steps ' +
        'required.\n\n' +
        'PepNationRX'
      );
    },
  },

  shipment_update: {
    subject: function () {
      return 'Your PepNationRX Shipment Update';
    },
    text: function (p) {
      const tracking = v(p, 'trackingNumber', '');
      const trackingLine = tracking
        ? '\nTracking number: ' + tracking + '\n'
        : '\n';
      return (
        'Hello ' + v(p, 'firstName', 'there') + ',\n\n' +
        'Your ' + v(p, 'treatmentName', 'treatment') + ' shipment status ' +
        'is now: ' + v(p, 'status', 'updated') + '.' + trackingLine +
        '\nPepNationRX'
      );
    },
  },

  billing_renewal: {
    subject: function () {
      return 'Your PepNationRX Plan Renews Soon';
    },
    text: function (p) {
      return (
        'Hello ' + v(p, 'firstName', 'there') + ',\n\n' +
        'Your ' + v(p, 'planName', 'plan') + ' renews on ' +
        v(p, 'renewalDate', 'your next billing date') + ' for ' +
        v(p, 'amount', 'the plan amount') + '. No action is needed to ' +
        'continue. You can manage your subscription from your dashboard.\n\n' +
        'PepNationRX'
      );
    },
  },

  checkin_due: {
    subject: function () {
      return 'Your Monthly Check-In Is Due';
    },
    text: function (p) {
      return (
        'Hello ' + v(p, 'firstName', 'there') + ',\n\n' +
        'Your monthly clinical check-in is due by ' +
        v(p, 'dueDate', 'soon') + '. Completing it keeps your protocol ' +
        'authorized without interruption. Sign in to complete it.\n\n' +
        'PepNationRX'
      );
    },
  },

  subscription_changed: {
    subject: function () {
      return 'Your Subscription Was Updated';
    },
    text: function (p) {
      return (
        'Hello ' + v(p, 'firstName', 'there') + ',\n\n' +
        'Your ' + v(p, 'planName', 'subscription') + ' was updated: ' +
        v(p, 'change', 'a change was applied') + '. If you did not make ' +
        'this change, contact support right away.\n\n' +
        'PepNationRX'
      );
    },
  },

  new_message: {
    subject: function () {
      return 'You Have A New Message From Your Care Team';
    },
    text: function (p) {
      return (
        'Hello ' + v(p, 'firstName', 'there') + ',\n\n' +
        'You have a new message from ' +
        v(p, 'senderName', 'your care team') + '. Sign in to your ' +
        'PepNationRX dashboard to read it and reply.\n\n' +
        'For your security, the message itself is not included in this ' +
        'email.\n\n' +
        'PepNationRX'
      );
    },
  },

  // Sent to a patient when an admin lands their requested visit at
  // 'scheduled' with a video room URL ready, so patients do not have to
  // refresh the dashboard to discover their booking.
  // Payload: firstName, scheduledFor (ISO timestamp), joinUrl.
  visit_scheduled: {
    subject: function () {
      return 'Your Video Visit Has Been Scheduled';
    },
    text: function (p) {
      const scheduledFor = v(p, 'scheduledFor', '');
      const joinUrl = v(p, 'joinUrl', '');
      const whenLine = scheduledFor
        ? 'It is scheduled for ' + scheduledFor + '.\n\n'
        : 'You will receive the time shortly.\n\n';
      const linkLine = joinUrl
        ? 'Join the visit when it is time:\n' + joinUrl + '\n\n'
        : 'Sign in to your PepNationRX dashboard to join when it is time.\n\n';
      return (
        'Hello ' + v(p, 'firstName', 'there') + ',\n\n' +
        'Your video visit with a licensed clinician has been ' +
        'scheduled.\n\n' +
        whenLine +
        linkLine +
        'PepNationRX'
      );
    },
  },

  // Phase 10: Sent to a patient when an admin moves a lab order to
  // status='resulted' and at least one analyte result row exists. The
  // result values themselves are NEVER included in the email body -
  // the patient signs in to review them with their care team.
  // Payload: firstName, panelName.
  lab_result_ready: {
    subject: function () {
      return 'Your Lab Results Are Ready';
    },
    text: function (p) {
      return (
        'Hello ' + v(p, 'firstName', 'there') + ',\n\n' +
        'Your ' + v(p, 'panelName', 'lab') + ' results are now available. ' +
        'Sign in to your PepNationRX dashboard to review them with your ' +
        'care team.\n\n' +
        'For your security, the result values are not included in this ' +
        'email.\n\n' +
        'PepNationRX'
      );
    },
  },
};

// Render a template to { subject, text }. Returns null for an unknown key so
// the service can fail safely rather than send an empty message.
function render(templateKey, payload) {
  const tpl = TEMPLATES[templateKey];
  if (!tpl) return null;
  return {
    subject: tpl.subject(payload || {}),
    text: tpl.text(payload || {}),
  };
}

// True when the template key is known.
function exists(templateKey) {
  return Object.prototype.hasOwnProperty.call(TEMPLATES, templateKey);
}

module.exports = {
  render: render,
  exists: exists,
  TEMPLATE_KEYS: Object.keys(TEMPLATES),
};

