// ============================================================================
// labs.service.js - the PepNationRX lab orders API client (Phase 10).
// ----------------------------------------------------------------------------
// Two endpoints for the patient surface:
//   GET  /api/patient/labs              list every lab order on file
//   GET  /api/patient/labs/:orderId     single order with its result rows
// Patient-side does not self-order labs; the admin Lab panel creates them.
// ============================================================================

'use strict';

import { api } from './api.js';

// Every lab order the signed-in patient has on file, newest-requested first.
// Resolves with { orders: [...] }; rejects with ApiError on a failed fetch.
export function fetchLabOrders() {
  return api.get('/api/patient/labs');
}

// A single lab order by id. Resolves with { order, results }.
export function fetchLabOrder(id) {
  return api.get('/api/patient/labs/' + encodeURIComponent(id));
}

// ============================================================================
// admin.service.js - the PepNationRX admin API client.
// ----------------------------------------------------------------------------
// Wraps the staff-only /api/admin endpoints. The endpoints themselves are
// gated server-side to the admin and support roles; this client only shapes
// the requests and returns the parsed responses.
// ============================================================================

'use strict';

import { api } from './api.js';

// Fetch the platform operations overview: revenue, subscription and user
// counts, and the open intake count.
export function fetchAdminDashboard() {
  return api.get('/api/admin/dashboard');
}

// Fetch the recent audit-log entries. `limit` is optional and capped at 500
// server-side (admin.model.recentAuditLog enforces Math.min(limit, 500)).
export function fetchAuditLog(limit) {
  const suffix =
    Number.isInteger(limit) && limit > 0 ? '?limit=' + limit : '';
  return api.get('/api/admin/audit-log' + suffix);
}

// Fetch every coupon for the staff coupon panel.
export function fetchCoupons() {
  return api.get('/api/admin/coupons');
}

// Create a coupon. `payload` carries code, type, value, and the optional
// limits and window fields.
export function createCoupon(payload) {
  return api.post('/api/admin/coupons', payload);
}

// Update a coupon's mutable terms. `fields` carries any of isActive,
// maxRedemptions, perUserLimit, minSubtotalCents, expiresAt, description.
export function updateCoupon(couponId, fields) {
  return api.patch('/api/admin/coupons/' + couponId, fields);
}

// Phase 9: fetch the admin visit work queue. Optional `status` filter
// narrows to a single state ('requested', 'scheduled', ...); absent
// filter returns the most recent 200 visits across all statuses.
export function fetchAdminVisits(status) {
  const suffix =
    typeof status === 'string' && status
      ? '?status=' + encodeURIComponent(status)
      : '';
  return api.get('/api/admin/visits' + suffix);
}

// Phase 9: update a visit. `fields` carries any subset of status,
// providerId, scheduledFor (ISO string), videoRoomUrl, videoRoomProvider.
// The backend auto-provisions a room URL when status flips to scheduled
// or in_progress and no URL is supplied.
export function updateAdminVisit(visitId, fields) {
  return api.patch('/api/admin/visits/' + visitId, fields);
}

// Phase 10: fetch the admin lab orders work queue. Optional `status`
// filter narrows to a single state ('requested', 'collected',
// 'processing', 'resulted', 'cancelled', 'abnormal_flagged'); absent
// filter returns the most recent 200 orders across all statuses.
export function fetchAdminLabs(status) {
  const suffix =
    typeof status === 'string' && status
      ? '?status=' + encodeURIComponent(status)
      : '';
  return api.get('/api/admin/labs' + suffix);
}

// Phase 10: create a lab order on behalf of a patient. `payload` carries
// userId (required), panelName (required), and the optional providerId,
// subscriptionId, panelReason, protocolCategory fields.
export function createAdminLab(payload) {
  return api.post('/api/admin/labs', payload);
}

// Phase 10: update a lab order. `fields` carries any subset of status,
// providerId, collectedAt (ISO string), resultedAt (ISO string), and
// providerNotes. Empty strings clear UUID and date fields.
export function updateAdminLab(orderId, fields) {
  return api.patch('/api/admin/labs/' + orderId, fields);
}

// Phase 10: append a single analyte result row to a lab order. `payload`
// carries analyteName, valueText, and optional unit, referenceRange,
// isAbnormal, observedAt (ISO).
export function addAdminLabResult(orderId, payload) {
  return api.post('/api/admin/labs/' + orderId + '/results', payload);
}

// ============================================================================
// pnrx-labs - the patient's lab orders surface (Phase 10).
// ----------------------------------------------------------------------------
// Lists every lab order the signed-in patient has on file, newest first.
// Each row has a status pill and an Expand button; expanding fetches the
// full order plus the result rows from /api/patient/labs/:orderId and
// renders an analyte table (abnormal results highlighted).
//
// In demo mode (`mode="demo"`) the API is not called; a host page can
// supply data via renderData(orders).
// ============================================================================

'use strict';

import { PnrxComponent, escapeHtml } from '../core/component.js';
import { fetchLabOrders, fetchLabOrder } from '../services/labs.service.js';

// Format an ISO timestamp as "Month DD, YYYY At HH:MM AM/PM". Empty
// values return the empty string so the caller can omit the line.
function longDateTime(value) {
  if (!value) return '';
  const d = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(d.getTime())) return '';
  const months = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];
  let hours = d.getHours();
  const minutes = d.getMinutes();
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12;
  if (hours === 0) hours = 12;
  const mm = (minutes < 10 ? '0' : '') + minutes;
  return (
    months[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear() +
    ' At ' + hours + ':' + mm + ' ' + ampm
  );
}

function humanStatus(status) {
  switch (status) {
    case 'requested':         return 'Requested';
    case 'collected':         return 'Sample Collected';
    case 'processing':        return 'Processing';
    case 'resulted':          return 'Results Ready';
    case 'cancelled':         return 'Cancelled';
    case 'abnormal_flagged':  return 'Abnormal Flagged';
    default:                  return status || 'Unknown';
  }
}

export class PnrxLabs extends PnrxComponent {
  constructor() {
    super();
    this.state = {
      status: 'loading',
      error: null,
      orders: [],
      expandedId: null,
      expandedResults: null,
      expandedBusy: false,
      expandedError: null,
    };
  }

  connectedCallback() {
    this._performRender();
    if (this.getAttribute('mode') !== 'demo' && !this._hasLoaded) {
      this._hasLoaded = true;
      this.load();
    }
  }

  async load() {
    this.setState({ status: 'loading', error: null });
    try {
      const res = await fetchLabOrders();
      this.setState({
        status: 'ready',
        orders: (res && res.orders) || [],
      });
    } catch (err) {
      this.setState({
        status: 'error',
        error:
          err && err.message
            ? err.message
            : 'Your Lab Orders Could Not Be Loaded.',
      });
    }
  }

  // Demo / host-page direct render.
  renderData(orders) {
    this.setState({ status: 'ready', orders: orders || [] });
  }

  async expandOrder(orderId) {
    if (this.state.expandedId === orderId) {
      // Collapse on repeat click.
      this.setState({
        expandedId: null,
        expandedResults: null,
        expandedError: null,
      });
      return;
    }
    this.setState({
      expandedId: orderId,
      expandedResults: null,
      expandedError: null,
      expandedBusy: true,
    });
    try {
      const res = await fetchLabOrder(orderId);
      this.setState({
        expandedBusy: false,
        expandedResults: (res && res.results) || [],
      });
    } catch (err) {
      this.setState({
        expandedBusy: false,
        expandedError:
          err && err.message
            ? err.message
            : 'The Results Could Not Be Loaded.',
      });
    }
  }

  render() {
    return (
      '<div class="pnrx-labs">' +
      this.renderHeader() +
      this.renderListSection() +
      '</div>'
    );
  }

  renderHeader() {
    return (
      '<header class="pnrx-labs__head">' +
      '<h2 class="pnrx-labs__title">Lab Results</h2>' +
      '<p class="pnrx-labs__sub">Review Every Lab Panel A Provider Has ' +
      'Ordered For You. Expand An Entry To See The Individual Analytes ' +
      'When Results Are Ready.</p>' +
      '</header>'
    );
  }

  renderListSection() {
    if (this.state.status === 'loading') {
      return (
        '<section class="pnrx-labs__card">' +
        '<p class="pnrx-labs__notice">Loading Your Lab Orders...</p>' +
        '</section>'
      );
    }
    if (this.state.status === 'error') {
      return (
        '<section class="pnrx-labs__card pnrx-labs__card--error">' +
        '<p class="pnrx-labs__notice">' +
        escapeHtml(this.state.error) +
        '</p>' +
        '<button type="button" class="pnrx-labs__expand-btn" data-action="retry">' +
        'Try Again</button>' +
        '</section>'
      );
    }
    if (!this.state.orders.length) {
      return (
        '<section class="pnrx-labs__card">' +
        '<p class="pnrx-labs__notice">No Lab Orders On File Yet. Your ' +
        'Care Team Will Order Labs As Part Of Your Protocol When ' +
        'Indicated.</p>' +
        '</section>'
      );
    }
    return this.renderList();
  }

  renderList() {
    const self = this;
    const items = this.state.orders
      .map(function (o) {
        return self.renderItem(o);
      })
      .join('');
    return (
      '<section class="pnrx-labs__card">' +
      '<h3 class="pnrx-labs__heading">Your Lab Orders</h3>' +
      '<ul class="pnrx-labs__list">' + items + '</ul>' +
      '</section>'
    );
  }

  renderItem(o) {
    const requested = longDateTime(o.requestedAt);
    const collected = o.collectedAt ? longDateTime(o.collectedAt) : '';
    const resulted = o.resultedAt ? longDateTime(o.resultedAt) : '';
    const status = o.status || 'unknown';
    const expanded = this.state.expandedId === o.id;
    const btnLabel = expanded ? 'Hide Results' : 'Expand';
    const reasonLine = o.panelReason
      ? '<p class="pnrx-labs__reason">' + escapeHtml(o.panelReason) + '</p>'
      : '';
    const collectedLine = collected
      ? '<p class="pnrx-labs__meta">Sample Collected: ' +
        escapeHtml(collected) + '</p>'
      : '';
    const resultedLine = resulted
      ? '<p class="pnrx-labs__meta">Results Returned: ' +
        escapeHtml(resulted) + '</p>'
      : '';
    return (
      '<li class="pnrx-labs__item">' +
      '<div class="pnrx-labs__item-head">' +
      '<span class="pnrx-labs__panel-name">' +
      escapeHtml(o.panelName || 'Lab Panel') +
      '</span>' +
      '<span class="pnrx-labs__status pnrx-labs__status--' +
      escapeHtml(status) +
      '">' +
      escapeHtml(humanStatus(status)) +
      '</span>' +
      '</div>' +
      '<p class="pnrx-labs__meta">Ordered: ' +
      escapeHtml(requested) + '</p>' +
      collectedLine +
      resultedLine +
      reasonLine +
      '<button type="button" class="pnrx-labs__expand-btn" ' +
      'data-action="expand" data-order-id="' +
      escapeHtml(o.id) + '">' +
      escapeHtml(btnLabel) +
      '</button>' +
      (expanded ? this.renderExpansion() : '') +
      '</li>'
    );
  }

  renderExpansion() {
    if (this.state.expandedBusy) {
      return (
        '<p class="pnrx-labs__notice">Loading Results...</p>'
      );
    }
    if (this.state.expandedError) {
      return (
        '<p class="pnrx-labs__notice pnrx-labs__notice--error">' +
        escapeHtml(this.state.expandedError) +
        '</p>'
      );
    }
    const results = this.state.expandedResults || [];
    if (!results.length) {
      return (
        '<p class="pnrx-labs__notice">No Result Values Yet.</p>'
      );
    }
    const rows = results
      .map(function (r) {
        const rowCls = r.isAbnormal
          ? ' class="pnrx-labs__results-row--abnormal"'
          : '';
        return (
          '<tr' + rowCls + '>' +
          '<td>' + escapeHtml(r.analyteName || '') + '</td>' +
          '<td>' + escapeHtml(r.valueText || '') + '</td>' +
          '<td>' + escapeHtml(r.unit || '') + '</td>' +
          '<td>' + escapeHtml(r.referenceRange || '') + '</td>' +
          '<td>' + (r.isAbnormal ? 'Yes' : 'No') + '</td>' +
          '</tr>'
        );
      })
      .join('');
    return (
      '<table class="pnrx-labs__results-table">' +
      '<thead><tr><th>Analyte</th><th>Value</th><th>Unit</th>' +
      '<th>Reference Range</th><th>Abnormal</th></tr></thead>' +
      '<tbody>' + rows + '</tbody>' +
      '</table>'
    );
  }

  afterRender() {
    const self = this;
    const retry = this.$('[data-action="retry"]');
    if (retry) {
      retry.addEventListener('click', function () {
        self.load();
      });
    }
    this.$$('[data-action="expand"]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        self.expandOrder(btn.getAttribute('data-order-id'));
      });
    });
  }
}

if (!customElements.get('pnrx-labs')) {
  customElements.define('pnrx-labs', PnrxLabs);
}

// ============================================================================
// pnrx-app-shell - the PepNationRX application shell.
// ----------------------------------------------------------------------------
// The single-page application frame. It owns the persistent header and footer,
// the hash router, and the route outlet, and it wires the cross-component
// flow: a catalog selection opens the triage intake, a completed intake opens
// checkout, and a completed checkout opens the patient dashboard.
//
// The footer carries a compact legal attribution line and links to the Terms Of
// Service, Privacy Policy, and Legal Notices routes defined in buildRoutes().
// The full MSO billing-agent consent disclosure is in pnrx-checkout.js where
// the patient actively acknowledges it before placing an order.
// ============================================================================

'use strict';

import { createRouter } from '../core/router.js';
import { isAuthenticated, getUser, subscribe } from '../store/session.js';
import { restoreSession, logout } from '../services/auth.service.js';
import { submitIntake } from '../services/intake.service.js';
import { showToast } from '../utils/toast.js';
import { configureApi } from '../services/api.js';
import { escapeHtml } from '../core/component.js';
// Phase 8: side-effect imports so /providers/:id can mount the element
// without depending on the host page including the script tag explicitly.
import './pnrx-provider-profile.js';
import './pnrx-visits.js';
import './pnrx-labs.js';

// Note: The full MSO billing-agent disclosure lives in pnrx-checkout.js
// where the patient actively acknowledges it before placing an order.
// The footer carries only the minimal required attribution line.

// Importing the feature components registers their custom elements so the
// router can create them by tag name.
import './pnrx-catalog.js';
import './pnrx-triage-form.js';
import './pnrx-checkout.js';
import './pnrx-patient-dashboard.js';
import './pnrx-message-thread.js';
import './pnrx-insurance-checker.js';
import './pnrx-membership.js';
import './pnrx-affiliate-dashboard.js';
import './pnrx-admin-dashboard.js';
import './pnrx-auth.js';

// Roles permitted to reach the admin dashboard.
const STAFF_ROLES = ['admin', 'support'];

// Path to the Pep Nation Rx logo (background removed, transparent PNG).
const PNRX_LOGO_SRC = 'assets/images/logo.png';


export class PnrxAppShell extends HTMLElement {
  constructor() {
    super();
    // The plan a visitor chose in the catalog, carried through intake to
    // checkout. Null until a catalog selection is made.
    this.pendingSelection = null;
    this.router = null;
    this.unsubscribe = null;
  }

  connectedCallback() {
    // Configure the API client. Vercel proxies /api/* to the Hetzner backend
    // so same-origin fetch works in production. For non-Vercel deployments,
    // set a `data-api-base` attribute on the <pnrx-app-shell> element or a
    // <meta name="api-base"> tag to override the base URL.
    const metaBase = document.querySelector('meta[name="api-base"]');
    const attrBase = this.getAttribute('data-api-base');
    const apiBase = attrBase || (metaBase && metaBase.getAttribute('content')) || '';
    configureApi({ baseUrl: apiBase });
    this.innerHTML =
      '<div class="pnrx-shell">' +
      '<header class="pnrx-shell__header">' +
      '<a class="pnrx-shell__brand" href="#/catalog" aria-label="PepNationRX">' +
      '<img class="pnrx-shell__logo" ' +
      'src="' + PNRX_LOGO_SRC + '" ' +
      'alt="PepNationRX" />' +
      '</a>' +
      '<button class="pnrx-shell__hamburger" aria-label="Menu" aria-expanded="false">' +
      '<svg width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" viewBox="0 0 24 24">' +
      '<line x1="3" y1="6" x2="21" y2="6"/>' +
      '<line x1="3" y1="12" x2="21" y2="12"/>' +
      '<line x1="3" y1="18" x2="21" y2="18"/>' +
      '</svg>' +
      '</button>' +
      '<nav class="pnrx-shell__nav" id="pnrx-shell-nav"></nav>' +
      '</header>' +
      '<main class="pnrx-shell__outlet" id="pnrx-shell-outlet"></main>' +
      '<footer class="pnrx-shell__footer">' +
      '<p class="pnrx-shell__legal">' +
      '&copy; ' + new Date().getFullYear() + ' PepNationRX - ' +
      'Telehealth Services Provided By Independent Licensed Practitioners. ' +
      'Not A Medical Provider. Not Insurance. Not Available In All States. ' +
      'Not For Emergencies - Call 911.' +
      '</p>' +
      '<p class="pnrx-shell__legal pnrx-shell__legal--links">' +
      '<a class="pnrx-shell__legal-link" href="#/terms">Terms Of Service</a>' +
      ' &middot; ' +
      '<a class="pnrx-shell__legal-link" href="#/privacy">Privacy Policy</a>' +
      ' &middot; ' +
      '<a class="pnrx-shell__legal-link" href="#/legal">Legal Notices</a>' +
      '</p>' +
      '</footer>' +
      '</div>';

    this.outlet = this.querySelector('#pnrx-shell-outlet');
    this.navEl = this.querySelector('#pnrx-shell-nav');

    // Mobile hamburger toggle
    var hamburger = this.querySelector('.pnrx-shell__hamburger');
    var nav = this.querySelector('#pnrx-shell-nav');
    if (hamburger) {
      hamburger.addEventListener('click', function () {
        var expanded = hamburger.getAttribute('aria-expanded') === 'true';
        hamburger.setAttribute('aria-expanded', String(!expanded));
        nav.classList.toggle('is-open');
      });
    }

    this.router = createRouter({
      outlet: this.outlet,
      fallback: '/catalog',
      routes: this.buildRoutes(),
      onChange: this.renderNav.bind(this),
    });

    // Re-render the nav whenever the session changes.
    this.unsubscribe = subscribe(this.renderNav.bind(this));

    this.bindFlowEvents();
    this.renderNav();

    // Restore a session from the refresh-token cookie, then start routing.
    restoreSession().finally(
      function () {
        this.router.start();
      }.bind(this)
    );
  }

  disconnectedCallback() {
    if (this.router) this.router.stop();
    if (this.unsubscribe) this.unsubscribe();
  }

  // -- Routing ---------------------------------------------------------------

  buildRoutes() {
    const self = this;
    return {
      '/catalog': function () {
        return document.createElement('pnrx-catalog');
      },
      '/intake': function () {
        return document.createElement('pnrx-triage-form');
      },
      '/checkout': function () {
        const el = document.createElement('pnrx-checkout');
        if (self.pendingSelection) {
          el.configure(self.pendingSelection);
        }
        return el;
      },
      '/dashboard': function () {
        if (!isAuthenticated()) {
          self.router.navigate('/login');
          return self.requireSignInNotice();
        }
        return document.createElement('pnrx-patient-dashboard');
      },
      '/messages': function () {
        if (!isAuthenticated()) {
          self.router.navigate('/login');
          return self.requireSignInNotice();
        }
        return document.createElement('pnrx-message-thread');
      },
      '/insurance': function () {
        if (!isAuthenticated()) {
          self.router.navigate('/login');
          return self.requireSignInNotice();
        }
        return document.createElement('pnrx-insurance-checker');
      },
      '/membership': function () {
        if (!isAuthenticated()) {
          self.router.navigate('/login');
          return self.requireSignInNotice();
        }
        return document.createElement('pnrx-membership');
      },
      '/affiliate': function () {
        if (!isAuthenticated()) {
          self.router.navigate('/login');
          return self.requireSignInNotice();
        }
        return document.createElement('pnrx-affiliate-dashboard');
      },
      '/providers/:providerId': function (params) {
        // Phase 8 public provider profile. No auth gate; the API enforces
        // profile_published. The element fetches its own data based on
        // the provider-id attribute the router supplies.
        const el = document.createElement('pnrx-provider-profile');
        if (params && params.providerId) {
          el.setAttribute('provider-id', params.providerId);
        }
        return el;
      },
      '/visits': function () {
        if (!isAuthenticated()) {
          self.router.navigate('/login');
          return self.requireSignInNotice();
        }
        return document.createElement('pnrx-visits');
      },
      '/labs': function () {
        if (!isAuthenticated()) {
          self.router.navigate('/login');
          return self.requireSignInNotice();
        }
        return document.createElement('pnrx-labs');
      },
      '/admin': function () {
        const user = getUser();
        if (!isAuthenticated()) {
          self.router.navigate('/login');
          return self.requireSignInNotice();
        }
        if (!user || STAFF_ROLES.indexOf(user.role) === -1) {
          const div = document.createElement('div');
          div.className = 'pnrx-shell__notice';
          div.textContent = 'This Area Is Restricted To Staff Accounts.';
          return div;
        }
        return document.createElement('pnrx-admin-dashboard');
      },
      '/login': function () {
        const el = document.createElement('pnrx-auth');
        el.setAttribute('mode', 'login');
        return el;
      },
      '/register': function () {
        const el = document.createElement('pnrx-auth');
        el.setAttribute('mode', 'register');
        return el;
      },
      '/terms': function () {
        return self.renderLegalPage(
          'Terms Of Service',
          'Our full Terms Of Service govern your use of this platform. ' +
          'This page will contain the complete text when the platform launches. ' +
          'Key terms: PepNationRX is a technology platform, not a medical provider. ' +
          'Clinical services are provided by independent, licensed practitioners. ' +
          'A prescription is not guaranteed and is at the sole discretion of the clinician.'
        );
      },
      '/privacy': function () {
        return self.renderLegalPage(
          'Privacy Policy',
          'Our full Privacy Policy details how we handle your information. ' +
          'This page will contain the complete text when the platform launches. ' +
          'We do not share your health data with advertisers. We maintain a Business ' +
          'Associate Agreement with all vendors who access protected health information.'
        );
      },
      '/legal': function () {
        return self.renderLegalPage(
          'Legal Notices',
          'Legal notices, MSO disclosure, and regulatory information. ' +
          'PepNationRX is a technology platform and management services organization. ' +
          'We do not provide medical advice or care. All clinical services are provided ' +
          'by independent, licensed medical practitioners. All compounded medications are ' +
          'fulfilled by licensed, independent 503A compounding pharmacies. ' +
          'PepNationRX acts solely as the designated billing agent. ' +
          'Compounded medications are not FDA-approved.'
        );
      },
    };
  }

  // A placeholder shown for a heartbeat while an unauthenticated visitor is
  // redirected to the sign-in screen.
  requireSignInNotice() {
    const div = document.createElement('div');
    div.className = 'pnrx-shell__notice';
    div.textContent = 'Please Sign In To Continue.';
    return div;
  }

  // A simple static page for legal routes (/terms, /privacy, /legal).
  // Renders a titled card with placeholder text until the full legal copy is
  // authored. Returns a DOM node so the router can mount it directly.
  renderLegalPage(title, body) {
    const div = document.createElement('div');
    div.className = 'pnrx-shell__legal-page';
    div.innerHTML =
      '<h2 class="pnrx-shell__legal-page-title">' +
      title +
      '</h2>' +
      '<p class="pnrx-shell__legal-page-body">' +
      body +
      '</p>';
    return div;
  }

  // -- Cross-component flow --------------------------------------------------

  bindFlowEvents() {
    const self = this;

    // A catalog selection carries a plan into the intake then checkout.
    this.addEventListener('catalog:select', function (event) {
      const d = event.detail || {};
      const months = d.planCadenceMonths || 1;
      self.pendingSelection = {
        protocolCategory: d.protocolCategory || null,
        planName: months === 1 ? 'Monthly' : months + '-Month Plan',
        treatmentName: d.treatmentName || '',
        treatmentSlug: d.treatmentSlug || '',
        cadenceMonths: months,
        pricePerMonthCents: d.planPriceCents || 0,
      };
      self.router.navigate('/intake');
    });

    // A completed intake is persisted to the backend so a provider can review
    // it, then advances to checkout when a plan was selected. The intake is
    // saved only for a signed-in patient; an anonymous visitor is routed
    // onward and will create an account before checkout. A save failure
    // blocks navigation to checkout because the backend requires an
    // intakeSubmissionId to link the order to the patient's clinical record.
    this.addEventListener('triage:submit', function (event) {
      const detail = event.detail || {};
      const proceed = function () {
        self.router.navigate(self.pendingSelection ? '/checkout' : '/dashboard');
      };
      if (!isAuthenticated()) {
        // Store the raw intake detail so we can submit it AFTER the patient
        // signs in. Without this, the intakeSubmissionId would be missing and
        // the clinical audit trail (intake → subscription) would be broken.
        if (self.pendingSelection) {
          self.pendingSelection._pendingIntakeDetail = detail;
        }
        self.router.navigate('/register');
        return;
      }
      submitIntake(detail)
        .then(function (result) {
          if (self.pendingSelection && result && result.submission) {
            self.pendingSelection.intakeSubmissionId = result.submission.id;
          }
          // Intake saved successfully — safe to proceed to checkout.
          proceed();
        })
        .catch(function () {
          // Intake save failed. Surface the error and keep the patient on
          // the current screen so they can retry. Do not navigate to checkout
          // without a valid intakeSubmissionId.
          showToast(
            'Your Intake Could Not Be Saved. Please Check Your Connection And Try Again.',
            'error'
          );
        });
    });

    // A completed checkout returns the patient to their dashboard.
    this.addEventListener('checkout:complete', function () {
      self.pendingSelection = null;
      showToast(
        'Order Received. A Provider Will Review Your Intake Shortly.',
        'success'
      );
      self.router.navigate('/dashboard');
    });

    // A checkout error surfaces as a toast in addition to the inline message.
    this.addEventListener('checkout:error', function (event) {
      const detail = event.detail || {};
      showToast(detail.message || 'Checkout Could Not Be Completed.', 'error');
    });

    // A successful sign-in or registration: if the patient was mid-flow (they
    // chose a treatment and went through intake before signing in), submit any
    // deferred intake then resume at checkout so the order can be completed.
    // Otherwise open the dashboard.
    this.addEventListener('auth:success', function () {
      showToast('You Are Signed In.', 'success');
      if (self.pendingSelection) {
        const deferredIntake = self.pendingSelection._pendingIntakeDetail;
        if (deferredIntake) {
          // The patient completed intake while anonymous — save it now that
          // we have an authenticated session so the intakeSubmissionId is
          // available for checkout.
          delete self.pendingSelection._pendingIntakeDetail;
          submitIntake(deferredIntake)
            .then(function (result) {
              if (result && result.submission) {
                self.pendingSelection.intakeSubmissionId = result.submission.id;
              }
              self.router.navigate('/checkout');
            })
            .catch(function () {
              // Intake save failed even after sign-in. Let the patient proceed
              // to checkout — the backend allows a null intakeSubmissionId for
              // edge-case recovery, but surface a warning.
              showToast(
                'Your Intake Could Not Be Saved. Your Order Will Still Be Placed.',
                'error'
              );
              self.router.navigate('/checkout');
            });
        } else {
          self.router.navigate('/checkout');
        }
      } else {
        self.router.navigate('/dashboard');
      }
    });
  }

  // -- Header navigation -----------------------------------------------------

  renderNav() {
    const links = [
      '<a class="pnrx-shell__link" href="#/catalog">Browse Treatments</a>',
      '<a class="pnrx-shell__link" href="#/intake">Start Intake</a>',
    ];
    if (isAuthenticated()) {
      const user = getUser();
      const label =
        user && user.first_name ? 'Hello, ' + escapeHtml(user.first_name) : 'My Dashboard';
      links.push('<a class="pnrx-shell__link" href="#/dashboard">' + label + '</a>');
      // Secure messaging is a patient-facing surface; staff use the provider
      // tools, not this nav link.
      if (!user || STAFF_ROLES.indexOf(user.role) === -1) {
        links.push(
          '<a class="pnrx-shell__link" href="#/messages">Messages</a>'
        );
        links.push(
          '<a class="pnrx-shell__link" href="#/visits">Video Visits</a>'
        );
        links.push(
          '<a class="pnrx-shell__link" href="#/labs">Lab Results</a>'
        );
        links.push(
          '<a class="pnrx-shell__link" href="#/insurance">Insurance</a>'
        );
        links.push(
          '<a class="pnrx-shell__link" href="#/membership">PepNationRX Plus</a>'
        );
      }
      if (user && STAFF_ROLES.indexOf(user.role) !== -1) {
        links.push(
          '<a class="pnrx-shell__link" href="#/admin">Admin Console</a>'
        );
      }
      links.push(
        '<button type="button" class="pnrx-shell__signout" ' +
          'data-action="signout">Sign Out</button>'
      );
    } else {
      links.push('<a class="pnrx-shell__link" href="#/login">Sign In</a>');
    }
    this.navEl.innerHTML = links.join('');

    const signout = this.navEl.querySelector('[data-action="signout"]');
    if (signout) {
      const self = this;
      signout.addEventListener('click', function () {
        logout().finally(function () {
          self.router.navigate('/catalog');
        });
      });
    }
  }
}

