// ============================================================================
// pnrx-admin-dashboard - the PepNationRX staff operations dashboard.
// ----------------------------------------------------------------------------
// Fetches GET /api/admin/dashboard and GET /api/admin/audit-log and renders the
// platform overview: revenue, user and subscription counts, the open-intake
// queue size, and the recent audit trail. The endpoints are staff-gated
// server-side, so a non-staff session simply sees a load error.
//
// In demo mode (the `mode="demo"` attribute) the component does not call the
// API; a host page supplies data with renderData(dashboard, auditEntries).
// ============================================================================

'use strict';

import { PnrxComponent, escapeHtml } from '../core/component.js';
import {
  fetchAdminDashboard,
  fetchAuditLog,
  fetchCoupons,
  createCoupon,
  updateCoupon,
  fetchAdminVisits,
  updateAdminVisit,
  fetchAdminLabs,
  createAdminLab,
  updateAdminLab,
  addAdminLabResult,
} from '../services/admin.service.js';
import { money, formatStamp, humanize } from '../utils/format.js';

// Visit status options, in the order an admin moves a visit through.
const VISIT_STATUS_OPTIONS = [
  'requested', 'scheduled', 'in_progress', 'completed',
  'cancelled', 'no_show',
];

// Lab order status options, in the order an admin moves an order
// through. abnormal_flagged is terminal and orthogonal to resulted.
const LAB_STATUS_OPTIONS = [
  'requested', 'collected', 'processing', 'resulted',
  'cancelled', 'abnormal_flagged',
];

// A blank lab order create form. Fields are read from the DOM at
// submit time (state is not bound per keystroke to keep input focus).
function emptyLabForm() {
  return {
    userId: '',
    panelName: '',
    panelReason: '',
    providerId: '',
  };
}

// Convert an ISO timestamp into the value a <input type="datetime-local">
// expects (local timezone, no seconds, no Z). Empty when no input.
function toDatetimeLocal(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const pad = function (n) { return (n < 10 ? '0' : '') + n; };
  return (
    d.getFullYear() + '-' +
    pad(d.getMonth() + 1) + '-' +
    pad(d.getDate()) + 'T' +
    pad(d.getHours()) + ':' +
    pad(d.getMinutes())
  );
}

// A blank coupon create form.
function emptyCouponForm() {
  return {
    code: '',
    type: 'percent',
    value: '',
    maxRedemptions: '',
    perUserLimit: '',
    minSubtotalCents: '',
    description: '',
  };
}

export class PnrxAdminDashboard extends PnrxComponent {
  constructor() {
    super();
    this.state = {
      status: 'loading', // loading | ready | error
      dashboard: null,
      auditLog: [],
      coupons: [],
      couponForm: emptyCouponForm(),
      couponBusy: false,
      couponError: null,
      couponNotice: null,
      // Phase 9 admin visit work queue.
      visits: [],
      visitStatusFilter: '', // '' = all
      visitBusyId: null,     // currently-saving visit id; one save at a time
      visitError: null,
      visitNotice: null,
      // Phase 10 admin lab work queue.
      labs: [],
      labStatusFilter: '', // '' = all
      labBusyId: null,
      labError: null,
      labNotice: null,
      labCreateForm: emptyLabForm(),
      labCreateBusy: false,
      error: null,
    };
  }

  connectedCallback() {
    this._performRender();
    if (this.getAttribute('mode') !== 'demo') {
      this.load();
    }
  }

  // Fetch the dashboard, audit log, coupons, and the visit work queue
  // together. Visit fetch failure should not block the rest of the
  // dashboard (the rest of the panels still render), so it is wrapped in
  // its own try/catch.
  async load() {
    this.setState({ status: 'loading', error: null });
    try {
      const [dashboard, auditResult, couponResult] = await Promise.all([
        fetchAdminDashboard(),
        fetchAuditLog(25),
        fetchCoupons(),
      ]);
      let visits = [];
      try {
        const visitResult = await fetchAdminVisits(
          this.state.visitStatusFilter || null
        );
        visits = (visitResult && visitResult.visits) || [];
      } catch (visitErr) {
        // Surface but do not fail the whole dashboard load.
        this.setState({
          visitError:
            visitErr && visitErr.message
              ? visitErr.message
              : 'The Visit Queue Could Not Be Loaded.',
        });
      }
      let labs = [];
      try {
        const labResult = await fetchAdminLabs(
          this.state.labStatusFilter || null
        );
        labs = (labResult && labResult.orders) || [];
      } catch (labErr) {
        this.setState({
          labError:
            labErr && labErr.message
              ? labErr.message
              : 'The Lab Queue Could Not Be Loaded.',
        });
      }
      this.setState({
        status: 'ready',
        dashboard: dashboard,
        auditLog: auditResult.entries || [],
        coupons: couponResult.coupons || [],
        visits: visits,
        labs: labs,
      });
    } catch (err) {
      this.setState({
        status: 'error',
        error:
          err && err.message
            ? err.message
            : 'The Admin Dashboard Could Not Be Loaded.',
      });
    }
  }

  // Render supplied data directly, bypassing the API. Used by the demo page.
  // Optional fourth arg supplies the visit queue for demo rendering.
  renderData(dashboard, auditEntries, coupons, visits, labs) {
    this.setState({
      status: 'ready',
      dashboard: dashboard,
      auditLog: auditEntries || [],
      coupons: coupons || [],
      visits: visits || [],
      labs: labs || [],
    });
  }

  // -- Rendering -------------------------------------------------------------

  render() {
    let body;
    if (this.state.status === 'loading') {
      body = this.renderState('Loading The Admin Dashboard', false);
    } else if (this.state.status === 'error') {
      body = this.renderState(this.state.error, true);
    } else {
      body = this.renderDashboard();
    }
    return '<div class="pnrx-admin">' + body + '</div>';
  }

  renderState(text, isError) {
    const cls = isError
      ? 'pnrx-admin__state pnrx-admin__state--error'
      : 'pnrx-admin__state';
    const retry = isError
      ? '<button type="button" class="pnrx-admin__btn" data-action="retry">' +
        'Try Again</button>'
      : '';
    return (
      '<div class="' + cls + '">' +
      '<p class="pnrx-admin__state-text">' + escapeHtml(text) + '</p>' +
      retry +
      '</div>'
    );
  }

  renderDashboard() {
    const d = this.state.dashboard || {};
    const summary = d.summary || {};
    return (
      '<header class="pnrx-admin__head">' +
      '<h2 class="pnrx-admin__title">Platform Operations</h2>' +
      '<p class="pnrx-admin__sub">A Staff Overview Of Revenue, Accounts, And ' +
      'The Clinical Review Queue.</p>' +
      '</header>' +
      this.renderStatGrid(summary) +
      this.renderCountTable(
        'Accounts By Role',
        d.usersByRole || [],
        'role'
      ) +
      this.renderCountTable(
        'Subscriptions By Status',
        d.subscriptionsByStatus || [],
        'status'
      ) +
      this.renderCoupons() +
      this.renderVisits() +
      this.renderLabs() +
      this.renderAuditTable()
    );
  }

  // -- Visit scheduling panel (Phase 9) -------------------------------------
  renderVisits() {
    const notice = this.state.visitNotice
      ? '<p class="pnrx-admin__coupon-notice" role="status">' +
        escapeHtml(this.state.visitNotice) +
        '</p>'
      : '';
    const error = this.state.visitError
      ? '<p class="pnrx-admin__coupon-error" role="alert">' +
        escapeHtml(this.state.visitError) +
        '</p>'
      : '';
    const self = this;
    const filterOptions = ['']
      .concat(VISIT_STATUS_OPTIONS)
      .map(function (s) {
        const label = s === '' ? 'All Statuses' : humanize(s);
        const sel =
          self.state.visitStatusFilter === s ? ' selected' : '';
        return (
          '<option value="' + escapeHtml(s) + '"' + sel + '>' +
          escapeHtml(label) +
          '</option>'
        );
      })
      .join('');
    return (
      '<section class="pnrx-admin__section">' +
      '<h3 class="pnrx-admin__section-title">Video Visit Queue</h3>' +
      '<div class="pnrx-admin__coupon-form">' +
      '<select data-visit-status-filter>' + filterOptions + '</select>' +
      '<button type="button" class="pnrx-admin__btn" ' +
      'data-action="refresh-visits">Apply Filter</button>' +
      '</div>' +
      notice +
      error +
      this.renderVisitTable() +
      '</section>'
