  renderVisitTable() {
    const rows = this.state.visits || [];
    if (!rows.length) {
      return '<p class="pnrx-admin__empty">No Visits Match.</p>';
    }
    const self = this;
    const body = rows
      .map(function (v) {
        const requested = v.requestedAt
          ? formatStamp(v.requestedAt)
          : '';
        const statusOptions = VISIT_STATUS_OPTIONS.map(function (s) {
          const sel = v.status === s ? ' selected' : '';
          return (
            '<option value="' + escapeHtml(s) + '"' + sel + '>' +
            escapeHtml(humanize(s)) +
            '</option>'
          );
        }).join('');
        const scheduledValue = toDatetimeLocal(v.scheduledFor);
        const roomValue = v.videoRoomUrl || '';
        const providerValue = v.providerId || '';
        const reason = v.patientReason
          ? '<div class="pnrx-admin__visit-reason">' +
            escapeHtml(v.patientReason) +
            '</div>'
          : '';
        const busy = self.state.visitBusyId === v.id;
        return (
          '<tr data-visit-row="' + escapeHtml(v.id) + '">' +
          '<td>' +
          '<div class="pnrx-admin__visit-when">' +
          escapeHtml(requested) +
          '</div>' +
          reason +
          '</td>' +
          '<td><select data-visit-field="status">' +
          statusOptions +
          '</select></td>' +
          '<td><input type="datetime-local" data-visit-field="scheduledFor" ' +
          'value="' + escapeHtml(scheduledValue) + '" /></td>' +
          '<td><input type="text" data-visit-field="videoRoomUrl" ' +
          'placeholder="Auto On Schedule" ' +
          'value="' + escapeHtml(roomValue) + '" /></td>' +
          '<td><input type="text" data-visit-field="providerId" ' +
