          (busy ? ' disabled' : '') + '>' +
          (busy ? 'Saving' : 'Save') +
          '</button></td>' +
          '</tr>'
        );
      })
      .join('');
    return (
      '<table class="pnrx-admin__table">' +
      '<thead><tr><th>Requested</th><th>Status</th>' +
      '<th>Scheduled For</th><th>Video Room Url</th>' +
      '<th>Provider Id</th><th>Action</th></tr></thead>' +
      '<tbody>' + body + '</tbody>' +
      '</table>'
    );
  }

  // -- Lab orders panel (Phase 10) -----------------------------------------
  renderLabs() {
    const notice = this.state.labNotice
      ? '<p class="pnrx-admin__coupon-notice" role="status">' +
        escapeHtml(this.state.labNotice) +
        '</p>'
      : '';
    const error = this.state.labError
      ? '<p class="pnrx-admin__coupon-error" role="alert">' +
