      '<div class="pnrx-admin__coupon-form">' +
      '<select data-lab-status-filter>' + filterOptions + '</select>' +
      '<button type="button" class="pnrx-admin__btn" ' +
      'data-action="refresh-labs">Apply Filter</button>' +
      '</div>' +
      '<div class="pnrx-admin__coupon-form">' +
      '<input type="text" data-lab-create-field="userId" ' +
      'placeholder="Patient User Id (Uuid)" ' +
      'value="' + escapeHtml(f.userId) + '" />' +
      '<input type="text" data-lab-create-field="panelName" ' +
      'placeholder="Panel Name (E.G. Lipid Panel)" ' +
      'value="' + escapeHtml(f.panelName) + '" />' +
      '<input type="text" data-lab-create-field="panelReason" ' +
      'placeholder="Reason (Optional)" ' +
      'value="' + escapeHtml(f.panelReason) + '" />' +
      '<input type="text" data-lab-create-field="providerId" ' +
      'placeholder="Provider Id (Optional)" ' +
      'value="' + escapeHtml(f.providerId) + '" />' +
      '<button type="button" class="pnrx-admin__btn" ' +
      'data-action="create-lab"' +
