          '<input type="text" data-lab-result-field="valueText" ' +
          'placeholder="Value" />' +
          '<input type="text" data-lab-result-field="unit" ' +
          'placeholder="Unit" />' +
          '<input type="text" data-lab-result-field="referenceRange" ' +
          'placeholder="Range" />' +
          '<label class="pnrx-admin__lab-abn-label">' +
          '<input type="checkbox" data-lab-result-field="isAbnormal" /> ' +
          'Abnormal' +
          '</label>' +
          '<button type="button" class="pnrx-admin__btn ' +
          'pnrx-admin__btn--sm" data-action="add-lab-result" ' +
          'data-lab-id="' + escapeHtml(o.id) + '"' +
          (busy ? ' disabled' : '') + '>Add Result</button>' +
          '</div>' +
          '</td>' +
          '</tr>'
        );
      })
      .join('');
    return (
      '<table class="pnrx-admin__table">' +
      '<thead><tr><th>Panel / Requested</th><th>Status</th>' +
      '<th>Collected At</th><th>Resulted At</th>' +
