  // The coupon management panel: a create form and the list of every coupon
  // with an activate / deactivate control.
  renderCoupons() {
    const notice = this.state.couponNotice
      ? '<p class="pnrx-admin__coupon-notice" role="status">' +
        escapeHtml(this.state.couponNotice) +
        '</p>'
      : '';
    const error = this.state.couponError
      ? '<p class="pnrx-admin__coupon-error" role="alert">' +
        escapeHtml(this.state.couponError) +
        '</p>'
      : '';
    return (
      '<section class="pnrx-admin__section">' +
      '<h3 class="pnrx-admin__section-title">Discount Coupons</h3>' +
      this.renderCouponForm() +
      notice +
      error +
      this.renderCouponTable() +
      '</section>'
    );
  }

  renderCouponForm() {
    const f = this.state.couponForm;
    const busy = this.state.couponBusy;
    function opt(value, label, selected) {
      return (
        '<option value="' +
        value +
        '"' +
        (selected ? ' selected' : '') +
        '>' +
        label +
        '</option>'
      );
    }
    return (
      '<div class="pnrx-admin__coupon-form">' +
      '<input type="text" data-coupon-field="code" placeholder="Code" ' +
      'value="' + escapeHtml(f.code) + '" />' +
      '<select data-coupon-field="type">' +
      opt('percent', 'Percent', f.type === 'percent') +
      opt('fixed', 'Fixed (Cents)', f.type === 'fixed') +
      '</select>' +
      '<input type="text" data-coupon-field="value" ' +
      'placeholder="Value" value="' + escapeHtml(f.value) + '" />' +
      '<input type="text" data-coupon-field="maxRedemptions" ' +
      'placeholder="Max Uses" value="' + escapeHtml(f.maxRedemptions) + '" />' +
      '<input type="text" data-coupon-field="perUserLimit" ' +
      'placeholder="Per User" value="' + escapeHtml(f.perUserLimit) + '" />' +
      '<input type="text" data-coupon-field="minSubtotalCents" ' +
      'placeholder="Min Order (Cents)" value="' +
      escapeHtml(f.minSubtotalCents) + '" />' +
      '<input type="text" data-coupon-field="description" ' +
      'placeholder="Description" value="' + escapeHtml(f.description) + '" />' +
      '<button type="button" class="pnrx-admin__btn" ' +
      'data-action="create-coupon"' + (busy ? ' disabled' : '') + '>' +
      (busy ? 'Saving' : 'Create Coupon') +
      '</button>' +
      '</div>'
    );
  }

  renderCouponTable() {
    const rows = this.state.coupons || [];
    if (!rows.length) {
      return '<p class="pnrx-admin__empty">No Coupons Yet.</p>';
    }
    const body = rows
      .map(function (c) {
        const value =
          c.type === 'percent'
            ? c.value + ' Percent'
            : money(c.value);
        const uses =
          String(c.redemptionCount) +
          (c.maxRedemptions != null ? ' / ' + c.maxRedemptions : '');
        const statusTag = c.isActive
          ? '<span class="pnrx-admin__tag pnrx-admin__tag--good">Active</span>'
          : '<span class="pnrx-admin__tag">Inactive</span>';
        const toggleLabel = c.isActive ? 'Deactivate' : 'Activate';
        return (
          '<tr>' +
          '<td>' + escapeHtml(c.code) + '</td>' +
          '<td>' + escapeHtml(humanize(c.type)) + '</td>' +
          '<td>' + escapeHtml(value) + '</td>' +
          '<td class="pnrx-admin__num">' + escapeHtml(uses) + '</td>' +
          '<td>' + statusTag + '</td>' +
          '<td><button type="button" class="pnrx-admin__btn ' +
          'pnrx-admin__btn--sm" data-toggle-coupon="' + escapeHtml(c.id) +
          '" data-coupon-active="' + (c.isActive ? '1' : '0') + '">' +
          toggleLabel + '</button></td>' +
          '</tr>'
        );
      })
      .join('');
    return (
      '<table class="pnrx-admin__table">' +
      '<thead><tr><th>Code</th><th>Type</th><th>Value</th>' +
      '<th class="pnrx-admin__num">Uses</th><th>Status</th>' +
      '<th>Action</th></tr></thead>' +
      '<tbody>' + body + '</tbody>' +
      '</table>'
    );
  }

  renderStatGrid(summary) {
    const cards = [
      { label: 'Live Monthly Recurring Revenue', value: money(summary.liveMrrCents) },
      { label: 'Settled Gross Revenue', value: money(summary.settledGrossCents) },
      {
        label: 'Settled Transactions',
        value: String(summary.settledTransactionCount || 0),
      },
      {
        label: 'Open Intake Queue',
        value: String(summary.openIntakeCount || 0),
      },
    ];
    const items = cards
      .map(function (card) {
        return (
          '<div class="pnrx-admin__stat">' +
          '<span class="pnrx-admin__stat-value">' +
          escapeHtml(card.value) +
          '</span>' +
          '<span class="pnrx-admin__stat-label">' +
          escapeHtml(card.label) +
          '</span>' +
          '</div>'
        );
      })
      .join('');
    return '<div class="pnrx-admin__stats">' + items + '</div>';
  }

  renderCountTable(title, rows, keyName) {
    if (!rows.length) {
      return (
        '<section class="pnrx-admin__section">' +
        '<h3 class="pnrx-admin__section-title">' + escapeHtml(title) + '</h3>' +
        '<p class="pnrx-admin__empty">No Records Yet.</p>' +
        '</section>'
      );
    }
    const body = rows
      .map(function (row) {
        return (
          '<tr><td>' +
          escapeHtml(humanize(row[keyName])) +
          '</td><td class="pnrx-admin__num">' +
          escapeHtml(String(row.count)) +
          '</td></tr>'
        );
      })
      .join('');
    return (
      '<section class="pnrx-admin__section">' +
      '<h3 class="pnrx-admin__section-title">' + escapeHtml(title) + '</h3>' +
      '<table class="pnrx-admin__table">' +
      '<thead><tr><th>' + escapeHtml(humanize(keyName)) +
      '</th><th class="pnrx-admin__num">Count</th></tr></thead>' +
      '<tbody>' + body + '</tbody>' +
      '</table>' +
      '</section>'
    );
  }

  renderAuditTable() {
    const rows = this.state.auditLog;
    if (!rows.length) {
      return (
        '<section class="pnrx-admin__section">' +
        '<h3 class="pnrx-admin__section-title">Recent Audit Activity</h3>' +
        '<p class="pnrx-admin__empty">No Audit Entries Yet.</p>' +
        '</section>'
      );
    }
    const body = rows
      .map(function (entry) {
        const phi = entry.phi_accessed
          ? '<span class="pnrx-admin__tag">PHI</span>'
          : '';
        return (
          '<tr>' +
          '<td>' + escapeHtml(formatStamp(entry.occurred_at)) + '</td>' +
          '<td>' + escapeHtml(entry.action || '') + ' ' + phi + '</td>' +
          '<td>' + escapeHtml(humanize(entry.actor_role) || 'System') + '</td>' +
          '<td>' + escapeHtml(entry.entity_type || '') + '</td>' +
          '</tr>'
        );
      })
      .join('');
    return (
      '<section class="pnrx-admin__section">' +
      '<h3 class="pnrx-admin__section-title">Recent Audit Activity</h3>' +
      '<table class="pnrx-admin__table">' +
      '<thead><tr><th>When</th><th>Action</th><th>Actor Role</th>' +
      '<th>Entity</th></tr></thead>' +
      '<tbody>' + body + '</tbody>' +
      '</table>' +
      '</section>'
    );
  }

  // -- Event binding ---------------------------------------------------------

  afterRender() {
    const self = this;
    const retry = this.$('[data-action="retry"]');
    if (retry) {
      retry.addEventListener('click', function () {
        self.load();
      });
    }

    const createBtn = this.$('[data-action="create-coupon"]');
    if (createBtn) {
      createBtn.addEventListener('click', function () {
        self.submitCoupon();
      });
    }

    this.$$('[data-toggle-coupon]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        self.toggleCoupon(
          btn.getAttribute('data-toggle-coupon'),
          btn.getAttribute('data-coupon-active') === '1'
        );
      });
    });

    // Phase 9: visit work queue handlers.
    const filterBtn = this.$('[data-action="refresh-visits"]');
    if (filterBtn) {
      filterBtn.addEventListener('click', function () {
        const sel = self.$('[data-visit-status-filter]');
        self.setState({
          visitStatusFilter: sel ? sel.value : '',
          visitNotice: null,
          visitError: null,
        });
        self.load();
      });
    }
    this.$$('[data-action="save-visit"]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        self.saveVisit(btn.getAttribute('data-visit-id'));
      });
    });

    // Phase 10: lab work queue handlers.
    const labFilter = this.$('[data-action="refresh-labs"]');
    if (labFilter) {
      labFilter.addEventListener('click', function () {
        const sel = self.$('[data-lab-status-filter]');
        self.setState({
          labStatusFilter: sel ? sel.value : '',
          labNotice: null,
          labError: null,
        });
        self.load();
      });
    }
    const labCreateBtn = this.$('[data-action="create-lab"]');
    if (labCreateBtn) {
      labCreateBtn.addEventListener('click', function () {
        self.submitLab();
      });
    }
    this.$$('[data-action="save-lab"]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        self.saveLab(btn.getAttribute('data-lab-id'));
      });
    });
    this.$$('[data-action="add-lab-result"]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        self.addLabResult(btn.getAttribute('data-lab-id'));
      });
    });
  }

  // -- Coupon actions --------------------------------------------------------

  // Read the coupon create form straight from the DOM. The form fields are not
  // bound to state per keystroke - the base component re-renders by replacing
  // innerHTML, which would drop input focus on every character - so the values
  // are collected only when an action runs.
  readCouponForm() {
    const self = this;
    function read(name) {
      const el = self.$('[data-coupon-field="' + name + '"]');
      return el ? el.value : '';
    }
    return {
      code: read('code'),
      type: read('type'),
      value: read('value'),
      maxRedemptions: read('maxRedemptions'),
      perUserLimit: read('perUserLimit'),
      minSubtotalCents: read('minSubtotalCents'),
      description: read('description'),
    };
  }

  // Create a coupon from the form. Optional numeric fields are omitted when
  // left blank so the backend applies its defaults.
  async submitCoupon() {
    if (this.state.couponBusy) return;
    const form = this.readCouponForm();
    const code = form.code.trim();
    const value = parseInt(form.value, 10);
    if (code === '' || !Number.isInteger(value) || value <= 0) {
      this.setState({
        couponForm: form,
        couponError: 'A Code And A Positive Value Are Required.',
        couponNotice: null,
      });
      return;
    }

    const payload = { code: code, type: form.type, value: value };
    function optPositiveInt(name, raw) {
      const n = parseInt(raw, 10);
      if (Number.isInteger(n) && n > 0) payload[name] = n;
    }
    optPositiveInt('maxRedemptions', form.maxRedemptions);
    optPositiveInt('perUserLimit', form.perUserLimit);
    const minSub = parseInt(form.minSubtotalCents, 10);
    if (Number.isInteger(minSub) && minSub >= 0) {
      payload.minSubtotalCents = minSub;
    }
    if (form.description.trim() !== '') {
      payload.description = form.description.trim();
    }

    this.setState({
      couponBusy: true,
      couponError: null,
      couponNotice: null,
      couponForm: form,
    });
    try {
      await createCoupon(payload);
      this.setState({
        couponBusy: false,
        couponForm: emptyCouponForm(),
        couponNotice: 'Coupon ' + code.toUpperCase() + ' Created.',
        couponError: null,
      });
      await this.load();
    } catch (err) {
      this.setState({
        couponBusy: false,
        couponForm: form,
        couponError:
          err && err.message
            ? err.message
            : 'The Coupon Could Not Be Created.',
      });
    }
  }

  // Activate or deactivate a coupon.
  async toggleCoupon(couponId, isCurrentlyActive) {
    if (this.state.couponBusy) return;
    this.setState({
      couponBusy: true,
      couponError: null,
      couponNotice: null,
      couponForm: this.readCouponForm(),
    });
    try {
      await updateCoupon(couponId, { isActive: !isCurrentlyActive });
      this.setState({ couponBusy: false });
      await this.load();
    } catch (err) {
      this.setState({
        couponBusy: false,
        couponError:
          err && err.message
            ? err.message
            : 'The Coupon Could Not Be Updated.',
      });
    }
  }

  // -- Visit actions (Phase 9) ----------------------------------------------

  // Pull the current values for a single visit row straight from the DOM.
  // Inputs are not bound to state per keystroke (we'd lose focus on every
  // character), so the values are collected only at submit time.
  readVisitForm(visitId) {
    const row = this.$('[data-visit-row="' + visitId + '"]');
    if (!row) return {};
    function read(field) {
      const el = row.querySelector('[data-visit-field="' + field + '"]');
      return el ? el.value : '';
    }
    return {
      status: read('status'),
      scheduledFor: read('scheduledFor'),
      videoRoomUrl: read('videoRoomUrl'),
      providerId: read('providerId'),
    };
  }

  // Save a single visit row. Only sends fields that actually changed
  // relative to the loaded state so the server doesn't overwrite a value
  // a co-admin set seconds ago. datetime-local values are converted to
  // ISO strings before sending; empty strings clear the field.
  async saveVisit(visitId) {
    if (this.state.visitBusyId) return;
    const form = this.readVisitForm(visitId);
    const original = (this.state.visits || []).find(function (v) {
      return v.id === visitId;
    });
    if (!original) {
      this.setState({
        visitError: 'That Visit Is No Longer In The Queue.',
        visitNotice: null,
      });
      return;
    }
    const payload = {};
    if (form.status && form.status !== original.status) {
      payload.status = form.status;
    }
    if (form.scheduledFor) {
      const iso = new Date(form.scheduledFor).toISOString();
      if (
        !original.scheduledFor ||
        new Date(original.scheduledFor).toISOString() !== iso
      ) {
        payload.scheduledFor = iso;
      }
    } else if (original.scheduledFor) {
      // Admin cleared the datetime input. Send the empty string so the
      // backend's clear branch (controller B2 fix) nulls the column.
      payload.scheduledFor = '';
    }
    const trimmedUrl = form.videoRoomUrl.trim();
    if (trimmedUrl !== (original.videoRoomUrl || '')) {
      payload.videoRoomUrl = trimmedUrl;
    }
    const trimmedProvider = form.providerId.trim();
    if (trimmedProvider !== (original.providerId || '')) {
      payload.providerId = trimmedProvider;
    }
    if (Object.keys(payload).length === 0) {
      this.setState({
        visitNotice: 'No Changes To Save.',
        visitError: null,
      });
      return;
    }
    this.setState({
      visitBusyId: visitId,
      visitError: null,
      visitNotice: null,
    });
    try {
      await updateAdminVisit(visitId, payload);
      this.setState({
        visitBusyId: null,
        visitNotice: 'Visit Saved.',
        visitError: null,
      });
      await this.load();
    } catch (err) {
      this.setState({
        visitBusyId: null,
        visitNotice: null,
        visitError:
          err && err.message
            ? err.message
            : 'The Visit Could Not Be Saved.',
      });
    }
  }

  // -- Lab actions (Phase 10) ----------------------------------------------

  // Read the lab create form straight from the DOM. Not bound to state
  // per keystroke - the base component re-renders by replacing innerHTML,
  // which would drop focus on every character.
  readLabCreateForm() {
    const self = this;
    function read(name) {
      const el = self.$('[data-lab-create-field="' + name + '"]');
      return el ? el.value : '';
    }
    return {
      userId: read('userId'),
      panelName: read('panelName'),
      panelReason: read('panelReason'),
      providerId: read('providerId'),
    };
  }

  async submitLab() {
    if (this.state.labCreateBusy) return;
    const form = this.readLabCreateForm();
    const userId = form.userId.trim();
    const panelName = form.panelName.trim();
    if (userId === '' || panelName === '') {
      this.setState({
        labCreateForm: form,
        labError: 'A Patient Id And A Panel Name Are Required.',
        labNotice: null,
      });
      return;
    }
    const payload = { userId: userId, panelName: panelName };
    if (form.panelReason.trim() !== '') {
      payload.panelReason = form.panelReason.trim();
    }
    if (form.providerId.trim() !== '') {
      payload.providerId = form.providerId.trim();
    }
    this.setState({
      labCreateBusy: true,
      labError: null,
      labNotice: null,
      labCreateForm: form,
    });
    try {
      await createAdminLab(payload);
      this.setState({
        labCreateBusy: false,
        labCreateForm: emptyLabForm(),
        labNotice: 'Lab Order Created.',
        labError: null,
      });
      await this.load();
    } catch (err) {
      this.setState({
        labCreateBusy: false,
        labCreateForm: form,
        labError:
          err && err.message
            ? err.message
            : 'The Lab Order Could Not Be Created.',
      });
    }
  }

  readLabForm(orderId) {
    const row = this.$('[data-lab-row="' + orderId + '"]');
    if (!row) return {};
    function read(field) {
      const el = row.querySelector('[data-lab-field="' + field + '"]');
      return el ? el.value : '';
    }
    return {
      status: read('status'),
      collectedAt: read('collectedAt'),
      resultedAt: read('resultedAt'),
      providerId: read('providerId'),
    };
  }

  async saveLab(orderId) {
    if (this.state.labBusyId) return;
    const form = this.readLabForm(orderId);
    const original = (this.state.labs || []).find(function (o) {
      return o.id === orderId;
    });
    if (!original) {
      this.setState({
        labError: 'That Lab Order Is No Longer In The Queue.',
        labNotice: null,
      });
      return;
    }
    const payload = {};
    if (form.status && form.status !== original.status) {
      payload.status = form.status;
    }
    function diffDate(field, originalVal) {
      const raw = form[field];
      if (raw) {
        const iso = new Date(raw).toISOString();
        if (!originalVal || new Date(originalVal).toISOString() !== iso) {
          payload[field] = iso;
        }
      } else if (originalVal) {
        payload[field] = '';
      }
    }
    diffDate('collectedAt', original.collectedAt);
    diffDate('resultedAt', original.resultedAt);
    const trimmedProvider = form.providerId.trim();
    if (trimmedProvider !== (original.providerId || '')) {
      payload.providerId = trimmedProvider;
    }
    if (Object.keys(payload).length === 0) {
      this.setState({
        labNotice: 'No Changes To Save.',
        labError: null,
      });
      return;
    }
    this.setState({
      labBusyId: orderId,
      labError: null,
      labNotice: null,
    });
    try {
      await updateAdminLab(orderId, payload);
      this.setState({
        labBusyId: null,
        labNotice: 'Lab Order Saved.',
        labError: null,
      });
      await this.load();
    } catch (err) {
      this.setState({
        labBusyId: null,
        labNotice: null,
        labError:
          err && err.message
            ? err.message
            : 'The Lab Order Could Not Be Saved.',
      });
    }
  }

  readLabResultForm(orderId) {
    const row = this.$('[data-lab-row="' + orderId + '"]');
    if (!row) return {};
    function read(field) {
      const el = row.querySelector(
        '[data-lab-result-field="' + field + '"]'
      );
      if (!el) return '';
      if (el.type === 'checkbox') return el.checked ? 'on' : '';
      return el.value;
    }
    return {
      analyteName: read('analyteName'),
      valueText: read('valueText'),
      unit: read('unit'),
      referenceRange: read('referenceRange'),
      isAbnormal: read('isAbnormal') === 'on',
    };
  }

  async addLabResult(orderId) {
    if (this.state.labBusyId) return;
    const form = this.readLabResultForm(orderId);
    const analyteName = (form.analyteName || '').trim();
    const valueText = (form.valueText || '').trim();
    if (analyteName === '' || valueText === '') {
      this.setState({
        labError: 'An Analyte Name And Value Are Required.',
        labNotice: null,
      });
      return;
    }
    const payload = {
      analyteName: analyteName,
      valueText: valueText,
      isAbnormal: form.isAbnormal === true,
    };
    if ((form.unit || '').trim() !== '') {
      payload.unit = form.unit.trim();
    }
    if ((form.referenceRange || '').trim() !== '') {
      payload.referenceRange = form.referenceRange.trim();
    }
    this.setState({
      labBusyId: orderId,
      labError: null,
      labNotice: null,
    });
    try {
      await addAdminLabResult(orderId, payload);
      this.setState({
        labBusyId: null,
        labNotice: 'Result Added.',
        labError: null,
      });
      await this.load();
    } catch (err) {
      this.setState({
        labBusyId: null,
        labNotice: null,
        labError:
          err && err.message
            ? err.message
            : 'The Result Could Not Be Added.',
      });
    }
  }
}

// Register the custom element once.
if (!customElements.get('pnrx-admin-dashboard')) {
  customElements.define('pnrx-admin-dashboard', PnrxAdminDashboard);
}

/* ============================================================================
   PEPNATIONRX - LAB RESULTS  (Phase 10)
   The patient surface for reviewing lab orders and their result rows.
   Mounted at /labs. Read-only - admins create orders; patients only
   expand orders to see individual analyte values.
   ============================================================================ */

pnrx-labs {
  display: block;
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

.pnrx-labs {
  max-width: 880px;
  margin: 0 auto;
  padding: var(--space-7) var(--layout-gutter);
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
}

/* -- Header ------------------------------------------------------------------ */
.pnrx-labs__head {
  text-align: center;
  margin-bottom: var(--space-2);
}

.pnrx-labs__title {
  font-size: var(--text-3xl);
  font-weight: var(--weight-bold);
  color: var(--canvas-700);
  margin: 0 0 var(--space-2);
  line-height: var(--leading-tight);
  letter-spacing: -0.02em;
}

.pnrx-labs__sub {
  font-size: var(--text-md);
  color: var(--canvas-400);
  margin: 0;
  line-height: var(--leading-base);
}

/* -- Card -------------------------------------------------------------------- */
.pnrx-labs__card {
  background: var(--white);
  border: 1px solid var(--canvas-200);
  border-radius: var(--radius-lg);
  box-shadow: var(--elev-2);
  padding: var(--space-6) var(--space-5);
}

.pnrx-labs__card--error .pnrx-labs__notice {
  color: var(--red-600);
}

.pnrx-labs__heading {
  font-size: var(--text-lg);
  font-weight: var(--weight-bold);
  color: var(--canvas-700);
  margin: 0 0 var(--space-3);
  letter-spacing: -0.01em;
}

.pnrx-labs__notice {
  font-size: var(--text-md);
  color: var(--canvas-500);
  margin: 0;
  text-align: center;
  padding: var(--space-3) 0;
  line-height: var(--leading-base);
}

.pnrx-labs__notice--error {
  color: var(--red-600);
}

/* -- List of orders ---------------------------------------------------------- */
.pnrx-labs__list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.pnrx-labs__item {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-4);
  background: var(--canvas-50, #f7f8fa);
  border: 1px solid var(--canvas-200);
  border-radius: var(--radius-md);
}

.pnrx-labs__item-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  flex-wrap: wrap;
}

.pnrx-labs__panel-name {
  font-size: var(--text-md);
  font-weight: var(--weight-semibold);
  color: var(--canvas-700);
  line-height: var(--leading-tight);
}

.pnrx-labs__meta {
  font-size: var(--text-sm);
  color: var(--canvas-500);
  margin: 0;
  line-height: var(--leading-base);
}

.pnrx-labs__reason {
  font-size: var(--text-sm);
  color: var(--canvas-700);
  margin: var(--space-2) 0 0;
  line-height: var(--leading-base);
  white-space: pre-wrap;
  word-break: break-word;
}

/* -- Status pill ------------------------------------------------------------- */
.pnrx-labs__status {
  display: inline-flex;
  align-items: center;
  padding: 3px var(--space-3);
  font-size: var(--text-xs);
  font-weight: var(--weight-semibold);
  border-radius: var(--radius-pill);
  background: var(--canvas-100);
  color: var(--canvas-700);
  white-space: nowrap;
}

.pnrx-labs__status--requested {
  background: var(--canvas-100);
  color: var(--canvas-700);
}

.pnrx-labs__status--collected,
.pnrx-labs__status--processing {
  background: var(--amber-100, #fef3c7);
  color: var(--amber-700, #b45309);
}

.pnrx-labs__status--resulted {
  background: var(--green-100);
  color: var(--green-600);
}

.pnrx-labs__status--cancelled {
  background: var(--canvas-200);
  color: var(--canvas-500);
}

.pnrx-labs__status--abnormal_flagged {
  background: var(--rose-100, #ffe4e6);
  color: var(--rose-600, #be123c);
}

/* -- Expand button ----------------------------------------------------------- */
.pnrx-labs__expand-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: flex-start;
  margin-top: var(--space-2);
  padding: 8px var(--space-4);
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-weight: var(--weight-bold);
  color: var(--white);
  background: var(--teal-500);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition:
    background var(--duration-fast) var(--ease-standard),
    box-shadow var(--duration-fast) var(--ease-standard);
}

.pnrx-labs__expand-btn:hover {
  background: var(--teal-400);
  box-shadow: 0 4px 14px rgba(22, 160, 140, 0.30);
}

/* -- Results table ----------------------------------------------------------- */
.pnrx-labs__results-table {
  width: 100%;
  margin-top: var(--space-3);
  border-collapse: collapse;
  font-size: var(--text-sm);
  background: var(--white);
  border: 1px solid var(--canvas-200);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.pnrx-labs__results-table th,
.pnrx-labs__results-table td {
  padding: var(--space-2) var(--space-3);
  text-align: left;
  border-bottom: 1px solid var(--canvas-200);
  color: var(--canvas-700);
  line-height: var(--leading-base);
}

.pnrx-labs__results-table thead {
  background: var(--canvas-50, #f7f8fa);
}

.pnrx-labs__results-table th {
  font-weight: var(--weight-bold);
  color: var(--canvas-500);
  font-size: var(--text-xs);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.pnrx-labs__results-table tr:last-child td {
  border-bottom: none;
}

.pnrx-labs__results-row--abnormal td {
  background: var(--rose-50, #fff1f2);
  color: var(--rose-600, #be123c);
  font-weight: var(--weight-semibold);
}

/* -- Mobile ------------------------------------------------------------------ */
@media (max-width: 600px) {
  .pnrx-labs {
    padding: var(--space-5) var(--space-4);
  }

  .pnrx-labs__title {
    font-size: var(--text-2xl);
  }

  .pnrx-labs__card {
    padding: var(--space-5) var(--space-4);
  }

  .pnrx-labs__results-table {
    font-size: var(--text-xs);
  }

  .pnrx-labs__results-table th,
  .pnrx-labs__results-table td {
    padding: var(--space-2);
  }
}
